/* bs-lactancia.sql — _BS_LACTANCIA_V1 (16-nov-2026)
   Permiso de lactancia acumulado (Ley 27240 y modificatorias): registro por trabajadora y jornadas por temporada.
   Nace directo en Supabase. Idempotente.
   Uso: cd C:\sistema-rl-verfrut\migracion ; node aplicar-sql.js bs-lactancia.sql */
CREATE TABLE IF NOT EXISTS rl."bs_gs_lactancia" (
  "id_fila" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fila" integer NOT NULL,
  "id" double precision,
  "codigo" extensions.citext,
  "dni" extensions.citext,
  "nombre" extensions.citext,
  "empresa" extensions.citext,
  "sede" extensions.citext,
  "fundo" extensions.citext,
  "cargo" extensions.citext,
  "supervisor" extensions.citext,
  "fecha_parto" timestamp,
  "parto_multiple" extensions.citext,
  "horas_dia" double precision,
  "fecha_retorno" timestamp,
  "fecha_fin" timestamp,
  "acuerdo_firmado" extensions.citext,
  "fecha_acuerdo" timestamp,
  "descansos" extensions.citext,
  "ausencias" extensions.citext,
  "estado" extensions.citext,
  "fecha_cierre" timestamp,
  "observaciones" extensions.citext,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext,
  "actualizado" timestamp DEFAULT (now() at time zone 'utc') NOT NULL,
  PRIMARY KEY ("id_fila")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ix_bs_gs_lactancia_ux_bs_gs_lactancia_fila" ON rl."bs_gs_lactancia" ("fila");
CREATE TABLE IF NOT EXISTS rl."bs_gs_lactancia__carga" (
  "fila" integer NOT NULL,
  "id" double precision,
  "codigo" extensions.citext,
  "dni" extensions.citext,
  "nombre" extensions.citext,
  "empresa" extensions.citext,
  "sede" extensions.citext,
  "fundo" extensions.citext,
  "cargo" extensions.citext,
  "supervisor" extensions.citext,
  "fecha_parto" timestamp,
  "parto_multiple" extensions.citext,
  "horas_dia" double precision,
  "fecha_retorno" timestamp,
  "fecha_fin" timestamp,
  "acuerdo_firmado" extensions.citext,
  "fecha_acuerdo" timestamp,
  "descansos" extensions.citext,
  "ausencias" extensions.citext,
  "estado" extensions.citext,
  "fecha_cierre" timestamp,
  "observaciones" extensions.citext,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext
);
INSERT INTO rl.bs_fuente (clave, fuente, por) VALUES ('bs_gs_lactancia','supabase','_BS_LACTANCIA_V1') ON CONFLICT (clave) DO NOTHING;
CREATE TABLE IF NOT EXISTS rl."bs_gs_lactancia_horarios" (
  "id_fila" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fila" integer NOT NULL,
  "id" double precision,
  "nombre" extensions.citext,
  "meses" extensions.citext,
  "desde_fecha" timestamp,
  "hasta_fecha" timestamp,
  "lv_horas" double precision,
  "sab_horas" double precision,
  "detalle" extensions.citext,
  "activo" extensions.citext,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext,
  "actualizado" timestamp DEFAULT (now() at time zone 'utc') NOT NULL,
  PRIMARY KEY ("id_fila")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ix_bs_gs_lactancia_horarios_ux_bs_gs_lactancia_horarios_fila" ON rl."bs_gs_lactancia_horarios" ("fila");
CREATE TABLE IF NOT EXISTS rl."bs_gs_lactancia_horarios__carga" (
  "fila" integer NOT NULL,
  "id" double precision,
  "nombre" extensions.citext,
  "meses" extensions.citext,
  "desde_fecha" timestamp,
  "hasta_fecha" timestamp,
  "lv_horas" double precision,
  "sab_horas" double precision,
  "detalle" extensions.citext,
  "activo" extensions.citext,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext
);
